-- The Loose Mooring: an inn that floats, and the place its lamp goes home to.

space {
  id = "di_inn",
  region = "dithers",
  name = "The Loose Mooring",
  description = "The inn is a barge. It is sixty feet long, tarred, with a thatched house built on the deck, a lantern at the bow, and a gangplank down to wherever it has fetched up tonight. At closing the landlord lets go the rope and goes to bed, and the Dithers takes the inn where it likes. In the morning it is somewhere else, facing another way. The regulars find it again every evening. They say a pint tastes better for a walk, and better still for a search.",
  palette = { bg = "#120f0a", text = "#dcd0b8", dim = "#7a6c54", accent = "#f0b458", border = "#503e26" },
  ambience = {
    flicker { color = "#ffb060", strength = 0.22 },
    steam { glyphs = "˙·∙", color = "#6c6456", rate = 0.25 },
    fireflies { glyphs = "°·", color = "#a8d8e0", rate = 0.12 },
  },

  things = {
    { name = "the landlord",
      icon = "☺",
      description = "Barnaby Float, a wide slow man with a tea towel over one shoulder and a look of permanent mild surprise at where he has woken up. The licence says the premises shall be at a fixed address. He keeps the licence in a frame. He says the address is fixed. It is the fen that moves.",
      things = {
        { name = "his log", description = "A ship's log, kept behind the bar. Every morning he writes down where the inn is. {i}Tues: Pym's Reach, bows east. Weds: against the heronry, bad smell. Thurs: do not know. Nice, though.{/}" },
        { name = "his mooring rope", description = "Coiled on a peg by the door, with an iron hook. At opening he throws it at the nearest thing. It has caught, at different times, a willow, a cow, the church spire and the Reeve." },
      },
      actions = {
        { "Order a pint", say "It comes in a pot with a lid, dark, with a head on it like pond foam. It tastes of malt, bog myrtle and a little smoke. \"Brewed aboard,\" he says. \"Water's from over the side. Boiled.\" He considers. \"Mostly it's the boiling people ask about.\"" },
        { "Ask where the inn was last night", say "\"Up by the turf diggings. Ezra's boys came aboard in their work boots and I'd peat on the floor a foot deep.\" He wipes a pot. \"Night before, we went aground on the old church. Woke up with the weathercock looking in at the window. Gave me a turn. Gave it one too, I should think.\"" },
        { "Ask who lights the lamp", set "di_knows_lamp",
          say "\"Nobody lights it.\" He nods toward the bow. \"He lights himself. Comes aboard at dusk, sits in the lantern till closing, and goes home. Been doing it since my grandfather's day. Same one, I believe. I pay him a saucer of lamp oil a week and he doesn't touch it.\" He leans on the bar. \"They've a place they go, in the alder carr. If you were to be on the bow at closing, and civil, I daresay he'd not mind company on the walk.\"" },
      } },
    { name = "the bar",
      description = "A ship's hatch cover on two barrels, scrubbed pale. There is a rail round the edge to stop the pots sliding when the inn swings at her rope. Regulars drink with one hand on the pot at all times, without knowing they do it, and can be told from visitors that way in any tavern in the kingdom.",
      things = {
        { name = "the row of pots",
          description = "Pewter, lidded, hung on hooks over the bar. Each has an owner and a mark.",
          things = {
            { name = "a pot with a fish on it", description = "Jabez Slodge's. It has been dropped overboard eleven times and brought back by eleven different people. The eleventh was a child who found it in a pike." },
            { name = "a pot with a pole on it", description = "Seth Quant's. It has never been seen in use. It is nevertheless empty and wet every night at closing, and he is never seen to come in." },
            { name = "three small pots on one hook", description = "Tied together with a red thread. {i}Tuesdays.{/} Nobody touches those. Nobody dusts them, and they are not dusty." },
            { name = "the visitor's pot", description = "It has a cork float soldered to the handle." },
          } },
        { name = "the taps", description = "Two. {i}Brown{/} and {i}Other{/}. The Other is paler and is made, as far as you can learn, when the inn drifts somewhere the water is different." },
        { name = "a jar of pickled samphire", description = "Green, salt, crisp. It comes from the far edge of the Dithers where the fen gives up and becomes the sea. A man walks it in once a year. He is treated as an ambassador." },
        { name = "the slate", description = "Tabs. Against each name, a small drawing of where the inn was on the night in question, in case of dispute. Several debts are denied on the grounds that the inn could not have been there." },
      } },
    { name = "the regulars",
      description = "A dozen, on benches bolted to the deck, steaming gently. They have come by boat, by stilt and by the plank walk, and one, by the look of him, straight across.",
      things = {
        { name = "two turf cutters", description = "Black to the elbow, drinking in silence, each with a brick of peat on the bench beside him like a hat. It is their fare for the fire. Everyone brings one. The fire of the Loose Mooring is made of the whole fen, a brick at a time." },
        { name = "a man telling the big eel", description = "Arms out. Further out. He turns sideways to get the bench into it. \"And that,\" he says, \"was between the eyes.\" Nobody is listening. He has told it every night for twenty years and it has grown a foot a year, like the real one." },
        { name = "a fowler and his dog", description = "A liver-coloured water dog, curled wet under the bench, and a man in a coat with forty pockets. The dog has its own pot, a saucer, on the floor. It drinks Brown.",
          actions = { { "Pat the dog", say "It thumps its tail twice and breathes out. The breath is duck, pond and beer. The fowler nods. \"He likes you. He don't like many. He bit the Excise.\"" } } },
        { name = "an old woman with a pipe", description = "In the corner by the stove, saying nothing, in a man's coat. She has outlived three landlords. When the inn comes to rest of a morning she is the one who says where it is, without looking out." },
      },
      actions = {
        { "Ask how they found the inn tonight", say "\"Followed the light.\" \"Smelled it.\" \"I never left,\" says a voice from under a bench. The old woman takes her pipe out. \"It's where it should be,\" she says. \"It always is. It's us that's somewhere else of a morning.\" This is received as the last word and you gather it usually is." },
      } },
    { name = "the stove",
      description = "An iron pot-belly on a hearth of bricks, with a chimney going up through the thatch in a collar of tin. It burns turf. On a still night the smoke stands up from the inn like a mast, and people take a bearing on it from three miles.",
      things = {
        { name = "the turf box", description = "Full of other people's bricks. You can tell the diggings they came from: black, brown, or a foxy red that burns with a smell of heather." },
        { name = "a row of boots", description = "Drying, upside down, on a rail round the stove. Twelve pairs. Under each a small pool is forming. The pools have joined and are making their way to the scuppers, since the floor, being a deck, is built for it." },
        { name = "a kettle of mulled ale", description = "With a hot poker standing in it and an apple going round. For those who came straight across." },
      },
      actions = { { "Add your brick", say "You have no brick. A turf cutter hands you one of his without a word. You put it in the stove. Something is felt to have been settled, and a place is made for you on the bench." } } },
    { name = "the galley",
      description = "Through a hatch behind the bar: a stove, a table that folds, and a cook wedged between them.",
      things = {
        { name = "the cook", description = "Mrs Float, as narrow as her husband is wide, who can turn a pancake in a space where another woman could not turn round. She cooks whatever comes over the side. The menu is chalked up fresh each day and consists of the word {i}EELS{/}." },
        { name = "the eel pie", description = "In a dish the size of a cartwheel, with a crust like a thatch and a china funnel in the middle. Under the crust: eel, parsley, onion and a jelly that sets on its own.",
          actions = { { "Ask for a slice", say "It is hot, green with parsley and it wobbles. You have never been sure about eel. You are sure now. Mrs Float watches you finish it and chalks a small tick on the wall, in a row of ticks, under the heading {i}CONVERTS{/}." } } },
        { name = "a string of dried fish", description = "Across the porthole, small, silver, stiff as spoons. She crumbles them into everything, including, some say, the beer." },
        { name = "the ship's cat", description = "Ginger, with one white foot, asleep in the bread crock. He is the only member of the household who has never once been surprised by where the inn is. He goes ashore every morning without looking and steps onto land." },
      } },
    { name = "the bilge",
      description = "Under a trap in the deck: the hold of the barge, which is the cellar. It is cool, black and smells of tar and hops. The barrels lie on the bottom boards with the fen a plank's thickness below them.",
      things = {
        barrel { name = "a barrel of Brown", description = "Chocked with wedges on both sides. It rolls a little when the inn swings, and Barnaby says the rolling is the secret. Other brewers leave it standing and wonder why." },
        barrel { name = "a barrel of Other", description = "Chalked with a place and a date: {i}off the spire, at the full moon{/}. He says the water is different there. Deeper, colder, and it has been through a church." },
        { name = "the pump", description = "A wooden bilge pump with a handle. Four hundred strokes at closing, every night, or the cellar comes up to meet the bar. The regulars take turns. It is counted as a round." },
        { name = "a plug", description = "An oak bung the size of a fist, in the bottom planking, with a mallet hanging beside it and a notice: {i}NO.{/}" },
        rat { name = "a water rat", description = "On a barrel, combing its whiskers. It came aboard on its own two years ago and has travelled further than most men in the village." },
      } },
    { name = "the cabins",
      description = "Aft, down three steps: four doors on a passage a shoulder wide. Beds for those who cannot find their way home, or whose home has not been found by the inn.",
      things = {
        { name = "the first cabin", description = "A bunk, a blanket and a round window an inch above the water. You wake in the night with a moorhen looking in. In the morning there is a different view and you have no idea whose." },
        { name = "the second cabin", description = "Let by the year to a gentleman from the Survey, who came to make a map of the Dithers. His instruments are on the bunk. His map is on the wall: a perfect outline, with nothing inside it but the words {i}see overleaf{/}, and nothing overleaf." },
        { name = "the third cabin", description = "Barnaby and Mrs Float's. There is a compass screwed to the ceiling over the bed. He looks at it when he wakes, to find out which way he is lying." },
        { name = "the fourth cabin",
          description = "The door is shut and tied with a red thread. A card: {i}Reserved. Tuesdays.{/}",
          things = {
            { name = "the keyhole", description = "You look. Three chairs, a round table, and on the table three cups and a book, face down, open. There is steam coming off the cups. It is not Tuesday." },
          } },
      } },
    { name = "the bow lantern",
      key = "di_bow_lantern",
      icon = "°",
      description = "An iron lantern on a post at the bow, with four panes of horn. The light in it is pale blue and has no wick. It sits in the middle of the lantern with nothing under it, quite still, like a cat in a window. It is a marsh light. It has taken a job.",
      things = {
        { name = "the saucer of oil", description = "On the floor of the lantern. Full. He has been paid a saucer a week for sixty years and has never drawn his wages. Barnaby tops it up for the look of the thing." },
        { name = "the horn panes", description = "Scratched on the inside, low down, with a great many very small marks, in rows. You think of a prisoner counting days. Then you look again. They are not days. They are people. One mark for each that he has seen home." },
      },
      actions = {
        { "Tap on the pane", say "It turns. It has no face and you would swear it is looking at you. It brightens by a shade, and dims again, in the way of somebody who is on duty and will talk to you after." },
        { "Wait on the bow till closing", when = flag "di_knows_lamp", set "di_wisp_home", fx "sparkle",
          say "The last regular goes down the plank. Barnaby lets go the rope and says goodnight to the fen. The light comes out through the horn without opening anything and hangs by your shoulder. Then it sets off across the water, low, at a walking pace, and there is a plank under your foot, and another. It looks back twice to see that you are keeping up. Ahead of you, in a wood of black alders, there is a glow like a town." },
      } },
    { name = "the gangplank",
      description = "A board with cleats, from the deck to whatever is nearest. Tonight it is a tussock. On the tussock is a boot scraper, which Barnaby carries ashore every evening and sets down, to make the place look permanent." },
    { name = "the sign",
      description = "Hung from the bow post: a painted rope, with one end made fast to nothing. Under it, the inn's name, and under that: {i}Est. here.{/} The word {i}here{/} is on a separate board, on hooks." },
    { name = "the skittles",
      description = "A set of nine pins and a cheese, on the afterdeck. The alley slopes whichever way the barge is lying. The local game allows for it: before each throw, the player may call for two men to go and stand on the other side.",
      actions = { { "Have a throw", say "You send the cheese down the deck. It curves left, with the list, takes the corner pin and goes over the side. Nobody stirs. A boy with a net on a pole fishes it out in one movement and hands it back, dripping. This is his whole employment and he is very good." } } },
    { name = "the floating garden",
      description = "A raft tied astern, heaped with earth, growing leeks, a row of beans and one hollyhock. Mrs Float's. It follows the inn round the Dithers on a painter, like a duckling. Twice it has arrived somewhere first." },
    { name = "the dark outside",
      description = "From the rail: black water, black reeds, and a sky with all its stars. No village light in sight, no shore. Then, low down, a blue spark shows among the reeds, and another, further off, and a third. They are all moving the same way, steadily, towards the same place. It is closing time all over the Dithers." },
  },

  exits = {
    { to = "di_stilts", label = "The plank walk back", description = "Ashore over the gangplank, and along the single board to the last post of the village." },
    { to = "di_wisp_hollow", label = "After the lamp",
      description = "Off the bow at closing, behind the light, over planks that are there when it is.",
      requires = flag "di_wisp_home", hidden = true },
  },
}

space {
  id = "di_wisp_hollow",
  region = "dithers",
  secret = true,
  name = "The Lodgings",
  description = "In the middle of an alder carr, where the trees stand in black water on roots like fingers, there is a dry hummock no bigger than a room. It is covered in jars. Pickle jars, jam jars, a physic bottle, a cracked lamp chimney, set down on the moss and wedged in the roots and hung from the branches on bits of string. In every one there is a light. This is where the marsh lights of the Dithers go when they have seen everybody home. Not one of them has ever been thanked, and they are all perfectly content.",
  palette = { bg = "#060a10", text = "#c4d0dc", dim = "#56667a", accent = "#a0d8f0", border = "#24405a" },
  ambience = {
    fireflies { glyphs = "°∘·", color = "#a8dcf0", rate = 0.6 },
    shimmer { color = "#3a6a88", strength = 0.2 },
    fog { color = "#0e1a22", speed = 0.08, strength = 0.3 },
  },

  things = {
    { name = "the jars",
      wonder = true,
      description = "Hundreds. Each one holds a flame the size of a thumb, blue at the heart and paler at the edge, burning on nothing. {magic}The whole hummock is lit like a chapel at a feast, and the black water all round holds every light a second time.{/} They dim when you come among them, out of manners, the way people lower their voices. Then, one by one, they come up again.",
      things = {
        { name = "a jam jar", description = "The label says {i}Damson{/}, and a year. The light in it has a faint purple tinge. It has lived there so long that you think it has taken the colour, like a room." },
        { name = "a jar with the lid on", description = "Screwed down tight, and the light inside turned low. You reach for it, and the lights nearest go sharp and bright. You take your hand away. It is not shut in. It is having an early night." },
        { name = "an empty jar", description = "Clean, on a stump of its own, with a sprig of bog myrtle in it. Its light went out over the reed beds, east, a long time ago, and stays there by the plank walk leading people round in a circle. The others keep the jar aired. They say it will come home when it has got somebody somewhere." },
        { name = "a very small jar", description = "A thimble, with a light in it no bigger than a seed. It is new this year. It is not allowed out past the first alder yet. It practises on moths." },
      },
      actions = {
        { "Sit down among them", say "You sit on the moss. After a while a jar on a string turns, though there is no wind, and then another, until every light on the hummock is facing you. Nothing is said. You have the strong impression of being looked over, in a kindly way, by a great many night nurses at once." },
      } },
    { name = "the lamp from the inn",
      icon = "°",
      description = "He has gone to the biggest jar, a stone bottle with the neck knocked off, at the top of the hummock. The others made room. He is the eldest and the only one in work, and there is a certain amount of pride in the carr about the position.",
      actions = {
        { "Ask why they do it", say "He does not speak. He goes to the edge of the hummock and hangs over the water, and you look where he is. There is a plank there, under the surface, green and soft. Beside it, another. Old walks, rotted, laid by people long gone, in every direction. The lights do not make the paths. They only remember where every one of them was." },
        { "Ask about the lantern", when = no(item "di_jack_lantern"), give "di_jack_lantern",
          say "He drifts to the root of the oldest alder. In a hollow there, on a bed of dry moss, is a turnip lantern gone hard as horn, with no candle. The lights all turn toward it. It is the lamp the first of them carried, when they still needed a thing to be seen by. He waits. Then, since you do not move, he nudges it an inch toward you with nothing at all. They have no use for it. They have become their own lamps. He would like it to go out and see somebody home." },
      } },
    { name = "the alders",
      description = "Black trunks in black water, each standing up on a cage of roots, with small dark cones and leaves like the ace of clubs. Alder is the tree that will grow with its feet wet. The fen people say that a wood of them is the nearest the Dithers comes to deciding.",
      things = {
        { name = "the roots", description = "Red where they are cut, like meat. Between them, in every gap, a jar. The trees have grown round some of them. There is a pickle jar half swallowed by a root, with the light inside still clear, looking out as from a bay window." },
        { name = "the cones", description = "No bigger than a fingernail, black, in bunches. They float. Each one that drops into the water carries off the reflection of one light, for a little way, and loses it." },
        { name = "the oldest alder", description = "Hollow, leaning, more hole than tree. Lights go in and out of it like bees. Whatever is inside it is brighter than the rest, and none of them will let you look." },
      } },
    { name = "the strings",
      description = "Every jar that hangs, hangs from a length of something: fishing line, bootlace, plaited rush, one from a gold watch chain. The lights cannot tie knots. The knots are tied. You look at them for a while. Some are sailors' knots and some are a child's, and one is a neat little bow.",
      things = {
        { name = "the watch chain", description = "With the watch still on it, stopped. Engraved on the back: {i}To Eli, from K.{/} He left it here, then, the night he came back quiet. He must have been brought as far as this, and seen them, and wanted to give something." },
      } },
    { name = "gifts",
      description = "At the foot of the hummock, on a flat root, a row of things set out as on a shelf. A clay pipe. A penny. A slice of seed cake, a week old. A baby's shoe. A pot of ale with a lid, full. The people of the Dithers do not thank the lights. It is not done. They only happen to leave things here, by accident, on their way somewhere else.",
      things = {
        { name = "the pot of ale", description = "From the Loose Mooring, with a pole scratched on it. Seth Quant's. So that is where it goes." },
        { name = "a folded paper", description = "In a child's hand: {i}dear lite thank you for bringing my da home he was not drownded he was only at the inn{/}." },
      },
      actions = { { "Leave something", say "You go through your pockets. You put down the sprig of bog myrtle from your hat. It is not much. A light comes down from a branch, in its jar, on its string, and hangs over the sprig for some time. Then it goes back up, and you would say that it went with a spring in its step." } } },
    { name = "the moss",
      description = "Deep, dry and green, over the whole hummock, with small red cups in it like sealing wax. Your boots make no sound. Nothing here makes any sound. Hundreds of flames, and not one of them crackles." },
    { name = "the water round the hummock",
      description = "Still, black, and full of lights. You count the ones in the jars and the ones in the water. There are more in the water.",
      things = {
        { name = "the extra lights", description = "Down there, among the reflections, a few that have no jar above them. You work it out slowly. The water is showing the whole carr, with every jar lit. Those are the ones who are still out, with somebody, on a plank somewhere in the dark. The water is keeping their places." },
      } },
    { name = "a moth",
      description = "Grey, large, going round the thimble jar in circles. The seed of light inside dodges about, trying to lead it. The moth will not be led. At last the moth settles on the rim and folds its wings, and the small light goes still, and you see that it has been shown, for the first time, how the job is done. You do not lead them. You wait where they need to be." },
    { name = "a ledger of bark",
      description = "A sheet of birch bark pinned to an alder with a thorn, covered in fine scratches in rows. The same marks as on the horn of the inn's lantern. Tally of the seen-home, for the whole carr, year on year.",
      things = {
        { name = "the last row", description = "Tonight's. Eleven marks, and a twelfth being made as you watch, by nothing, slowly, line by line. That one is you." },
        { name = "a row with a gap", description = "Far up the sheet. Thirty marks, and one space left empty, with a ring scratched round it. They went back for that one for years. The ring has been gone over so many times it is cut right through the bark." },
      } },
    { name = "the plank you came by",
      description = "You look back. There is no plank. There is black water and alder root as far as the lights reach. The lamp from the inn is waiting at the edge, low, and when you step toward him there is wood under your foot again. It was always there. You only cannot find it by yourself." },
    { name = "a frog",
      icon = "f",
      description = "On the moss, by a jar, warming itself at a light that gives no heat. It seems satisfied. It may be that for a frog the look of the thing is enough." },
    { name = "the quiet",
      description = "No wind gets in here. No bittern, no reed. Only, at long intervals, a drop falling from an alder leaf into the water, and every light on the hummock leaning very slightly toward the sound, in case it was somebody." },
  },

  exits = {
    { to = "di_inn", label = "Back behind the lamp", description = "He will see you to the gangplank. It is what he does." },
  },
}
